import{_ as t,o as e,c as n,a2 as s}from"./chunks/framework.CFuv5BrO.js";const u=JSON.parse('{"title":"总体架构与数据流","description":"Hearth 的北极星架构、七个平面、任务数据流、部署形态与架构演进。","frontmatter":{"title":"总体架构与数据流","description":"Hearth 的北极星架构、七个平面、任务数据流、部署形态与架构演进。","outline":[2,3]},"headers":[],"relativePath":"architecture/overview.md","filePath":"architecture/overview.md","lastUpdated":1793706118000}'),d={name:"architecture/overview.md"};function l(r,a,p,o,i,c){return e(),n("div",null,[...a[0]||(a[0]=[s(`<p class="eyebrow">SYSTEM DESIGN</p><h1 id="总体架构与数据流" tabindex="-1">总体架构与数据流 <a class="header-anchor" href="#总体架构与数据流" aria-label="Permalink to &quot;总体架构与数据流&quot;">​</a></h1><p class="lead">七个平面如何协作，状态如何流动，系统如何从最小产品长成完整 Agent OS。</p><h2 id="北极星架构" tabindex="-1">北极星架构 <a class="header-anchor" href="#北极星架构" aria-label="Permalink to &quot;北极星架构&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用户 / CLI / Web / Mobile / IM</span></span>
<span class="line"><span>            ↓</span></span>
<span class="line"><span>     Experience Plane</span></span>
<span class="line"><span>     任务卡 · 审批 · 产物 · 接管</span></span>
<span class="line"><span>            ↓</span></span>
<span class="line"><span>      Personal Gateway</span></span>
<span class="line"><span>   身份 · 渠道 · 设备 · 注意力入口</span></span>
<span class="line"><span>            ↓</span></span>
<span class="line"><span>       Control Plane</span></span>
<span class="line"><span>  触发 · 策略 · Mandate · 调度 · Watchdog</span></span>
<span class="line"><span>            ↓</span></span>
<span class="line"><span>      Durable Harness</span></span>
<span class="line"><span>  任务图 · 预算 · lease · 重试 · 恢复</span></span>
<span class="line"><span>            ↓</span></span>
<span class="line"><span>       Executor Layer</span></span>
<span class="line"><span> Native · Codex · Connector · Browser</span></span>
<span class="line"><span> GUI · Document/Data · Human</span></span>
<span class="line"><span>            ↓</span></span>
<span class="line"><span>     Execution Gateway</span></span>
<span class="line"><span> 工作区 · Sandbox · 网络 · Credential Broker</span></span>
<span class="line"><span>            ↓</span></span>
<span class="line"><span>  Event Log / Artifacts / Receipts</span></span>
<span class="line"><span>       ↓              ↓</span></span>
<span class="line"><span>   Memory OS      Evolution OS</span></span></code></pre></div><p>所有事实进入 Event Log；所有外部副作用经过 outbox、幂等键和 Receipt；所有界面状态都是投影，不是事实源。</p><h2 id="七个平面" tabindex="-1">七个平面 <a class="header-anchor" href="#七个平面" aria-label="Permalink to &quot;七个平面&quot;">​</a></h2><table tabindex="0"><thead><tr><th>平面</th><th>责任</th><th>不承担</th></tr></thead><tbody><tr><td>Experience Plane</td><td>任务卡、审批、产物、接管、通知</td><td>直接执行业务逻辑或写数据库</td></tr><tr><td>Personal Gateway</td><td>身份、渠道归一化、设备注册、注意力入口</td><td>长任务推理</td></tr><tr><td>Control Plane</td><td>意图、触发、策略、Mandate、调度、Watchdog</td><td>持有长期凭据</td></tr><tr><td>Durable Harness</td><td>任务图、路由、预算、重试、lease、恢复</td><td>绕过策略执行外部动作</td></tr><tr><td>Executor Layer</td><td>Native、Codex、Connector、Browser、GUI、Document/Data、Human 的统一协议</td><td>自行扩大权限或修改 Policy</td></tr><tr><td>Execution Gateway</td><td>工作区、Sandbox、浏览器、GUI、网络、Credential Broker</td><td>决定“该不该做”</td></tr><tr><td>Memory / Evolution</td><td>个人上下文、记忆、技能、评估、晋升和回滚</td><td>成为事实源</td></tr></tbody></table><p>Event Log 贯穿所有平面，是状态、审计、恢复和 UI 的源头。</p><h2 id="一次任务的完整数据流" tabindex="-1">一次任务的完整数据流 <a class="header-anchor" href="#一次任务的完整数据流" aria-label="Permalink to &quot;一次任务的完整数据流&quot;">​</a></h2><ol><li>用户或 Source 产生事件。</li><li>Gateway 归一化 Event，去重并记录来源。</li><li>Control Plane 判断：忽略 / 观察 / 建议 / 创建 Task。</li><li>Policy 与 Mandate 检查范围、风险、预算和审批要求。</li><li>Token Router 选择最小可行模型和执行层级。</li><li>Context Compiler 构建 Task Pack。</li><li>Harness 创建 Ticket、Assignment 和 outbox 记录。</li><li>Executor 在受限环境执行，持续产生 WorkerEvent。</li><li>Execution Gateway 通过 Broker 完成获批副作用。</li><li>产物、Receipt、失败和人工操作写入 Event Log。</li><li>验证器决定完成、重试、换执行器或转人工。</li><li>Memory 写入候选记忆；Evolution 收集轨迹。</li><li>UI 从投影生成任务卡、通知和产物视图。</li></ol><h2 id="部署形态" tabindex="-1">部署形态 <a class="header-anchor" href="#部署形态" aria-label="Permalink to &quot;部署形态&quot;">​</a></h2><table tabindex="0"><thead><tr><th>形态</th><th>组成</th><th>目标</th></tr></thead><tbody><tr><td>Local</td><td><code>hearth</code> CLI + <code>hearthd</code> + SQLite + Docker</td><td>第一阶段和 dogfood</td></tr><tr><td>Hybrid</td><td>本地状态与设备能力 + 云端模型/沙箱</td><td>资源不足或远程执行</td></tr><tr><td>Self-hosted Server</td><td>常驻 Gateway + 多设备 agentd + 可选远程 Sandbox</td><td>长期在线和多设备</td></tr></tbody></table><p>第一阶段不引入微服务。单进程、单写者、SQLite 足以支撑早期。模块边界靠接口、schema 和测试保证，而不是先拆网络服务。</p><h2 id="启动形态" tabindex="-1">启动形态 <a class="header-anchor" href="#启动形态" aria-label="Permalink to &quot;启动形态&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>hearthd</span></span>
<span class="line"><span>  ├─ local gateway / IPC / web API</span></span>
<span class="line"><span>  ├─ scheduler / watcher / trigger</span></span>
<span class="line"><span>  ├─ task queue / event log / outbox</span></span>
<span class="line"><span>  ├─ token router / context compiler / budget governor</span></span>
<span class="line"><span>  ├─ executor supervisor</span></span>
<span class="line"><span>  ├─ device registry / capability catalog / lease manager</span></span>
<span class="line"><span>  ├─ execution gateway / sandbox manager</span></span>
<span class="line"><span>  ├─ watchdog / health / backup</span></span>
<span class="line"><span>  └─ pairing / event sync / device revocation</span></span></code></pre></div><p>必须考虑开机自启、终端关闭后继续运行、休眠唤醒、网络中断、认证过期、执行器崩溃、版本升级、资源回收、手机断开和重新配对。</p><h2 id="架构演进" tabindex="-1">架构演进 <a class="header-anchor" href="#架构演进" aria-label="Permalink to &quot;架构演进&quot;">​</a></h2><p>Hearth 不在第一天实现最终架构图上的全部模块。架构随产品增量逐步长出来，但核心不变量保持：</p><table tabindex="0"><thead><tr><th>产品形态</th><th>架构增量</th><th>继续保持不变</th></tr></thead><tbody><tr><td>Stage 0 可点击原型</td><td>Web 原型、UI 数据契约、模拟投影</td><td>任务卡优先、状态诚实、一个主动作</td></tr><tr><td>Stage 1 本地 MVP</td><td>单进程 <code>hearthd</code>、SQLite WAL、Event Log、Codex、基础审批与产物</td><td>事实源、恢复、验证、副作用回执</td></tr><tr><td>Stage 2 日常操作员</td><td>Connector、Browser、Document/Data、Context Compiler、Memory v0</td><td>最小权限、来源、幂等、Token 预算</td></tr><tr><td>Stage 3 桌面操作员</td><td>设备 agentd、GUI Executor、接管与桌面隔离</td><td>单写者、审计、审批、失败恢复</td></tr><tr><td>Stage 4 主动个人 Agent</td><td>Trigger、注意力预算、手机 PWA、推送与配对</td><td>低打扰、可撤销、主动模式可暂停</td></tr><tr><td>Stage 5 记忆与进化 OS</td><td>Memory OS、Evolution OS、技能评估与回滚</td><td>provenance、遗忘、权限交集、可回滚</td></tr><tr><td>Stage 6 Personal Agent OS v1.0</td><td>多设备同步、离线队列、迁移、长期运行与配额</td><td>一个逻辑 Agent、事件一致、设备可撤销</td></tr></tbody></table><p><strong>架构可以分阶段扩展，但产品形态不能分阶段补课。</strong> 每个阶段都必须有与其架构复杂度匹配的完整用户路径。</p><h2 id="本章结论" tabindex="-1">本章结论 <a class="header-anchor" href="#本章结论" aria-label="Permalink to &quot;本章结论&quot;">​</a></h2><p>架构的价值不是模块数量，而是让“任务、授权、执行、证据和恢复”沿同一条可审计链路流动。Stage 0 先定义契约，Stage 1 用最小真实链路实现它，之后逐步扩展平面，不改变事实源和权限边界。</p>`,23)])])}const b=t(d,[["render",l]]);export{u as __pageData,b as default};
